details.command:
kubectl exec -n default app-1 -- sh -c '
curl -sS -o /dev/null -w "app-0: %{http_code}
" http://app-0.app/ 2>/dev/null || curl -sS -o /dev/null -w "app-0: %{http_code}
" http://app-0.app.default.svc.cluster.local/ 2>/dev/null
curl -sS -o /dev/null -w "app-1: %{http_code}
" http://app-1.app/ 2>/dev/null || curl -sS -o /dev/null -w "app-1: %{http_code}
" http://app-1.app.default.svc.cluster.local/ 2>/dev/null'
echo "--- HTTP body check ---"; kubectl exec -n default app-0 -- sh -c 'curl -sS -o /tmp/body.html http://app-0.app/ | head -5; echo "bytes=$(wc -c < /tmp/body.html)"' 2>&1
